
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_pbeloc_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_pbeloc", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-7.668228711915409e-02, -7.560176136909333e-02, -7.404111639217506e-02, -7.178147529211887e-02, -6.849610082333908e-02, -6.368525009258273e-02, -5.655763486250566e-02, -4.583545777854351e-02, -2.987741935932998e-02, -1.123949328565114e-02, -4.305045770797134e-03, -4.001136446405659e-02, -4.875054969830774e-02, -3.189757781332337e-02, -9.701710638162003e-03, -6.801546269049048e-04, -7.078664734943643e-06, -6.943991578331783e-09, -3.015347094179672e-13, -2.131906546160414e-19]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


